/**
 * Unit tests for XYPlot.clone().
 */
public class XYPlot_clone_TriageGen2Test {

    private XYPlot plot;
    private XYDataset dataset;
    private ValueAxis domainAxis;
    private ValueAxis rangeAxis;
    private XYItemRenderer renderer;

    @Before
    public void setUp() {
        dataset = mock(XYDataset.class);
        domainAxis = new NumberAxis("Domain");
        rangeAxis = new NumberAxis("Range");
        renderer = mock(XYItemRenderer.class);
        plot = new XYPlot(dataset, domainAxis, rangeAxis, renderer);
    }

    @Test
    public void testCloneBasicProperties() throws CloneNotSupportedException {
        XYPlot clone = (XYPlot) plot.clone();

        assertNotNull(clone);
        assertNotSame(plot, clone);

        // Verify axes are cloned and linked back
        assertNotSame(plot.getDomainAxis(), clone.getDomainAxis());
        assertEquals(plot.getDomainAxis().getLabel(), clone.getDomainAxis().getLabel());
        assertEquals(clone, clone.getDomainAxis().getPlot());

        assertNotSame(plot.getRangeAxis(), clone.getRangeAxis());
        assertEquals(plot.getRangeAxis().getLabel(), clone.getRangeAxis().getLabel());
        assertEquals(clone, clone.getRangeAxis().getPlot());

        // Verify dataset listeners (datasets are not cloned, but listener should be added)
        verify(dataset, atLeastOnce()).addChangeListener(clone);
    }

    @Test
    public void testCloneWithMultipleAxes() throws CloneNotSupportedException {
        plot.setDomainAxis(1, new NumberAxis("Domain 2"), false);
        plot.setRangeAxis(1, new NumberAxis("Range 2"), false);

        XYPlot clone = (XYPlot) plot.clone();

        assertEquals(2, clone.getDomainAxisCount());
        assertEquals(2, clone.getRangeAxisCount());
        assertEquals("Domain 2", clone.getDomainAxis(1).getLabel());
        assertEquals(clone, clone.getDomainAxis(1).getPlot());
    }

    @Test
    public void testCloneWithNullAxes() throws CloneNotSupportedException {
        plot.clearDomainAxes();
        plot.clearRangeAxes();

        XYPlot clone = (XYPlot) plot.clone();

        assertEquals(0, clone.getDomainAxisCount());
        assertEquals(0, clone.getRangeAxisCount());
    }

    @Test
    public void testCloneWithDatasets() throws CloneNotSupportedException {
        XYDataset dataset2 = mock(XYDataset.class);
        plot.setDataset(1, dataset2);

        XYPlot clone = (XYPlot) plot.clone();

        assertEquals(2, clone.getDatasetCount());
        verify(dataset2, atLeastOnce()).addChangeListener(clone);
    }

    @Test
    public void testCloneWithPublicCloneableRenderer() throws CloneNotSupportedException {
        // Create a mock renderer that implements PublicCloneable
        // Since we cannot easily mock interfaces with specific inheritance in all environments, 
        // we use a concrete stub if needed, but here we simulate the logic.
        XYItemRenderer publicRenderer = spy(new XYItemRenderer() {
            @Override
            public Object clone() throws CloneNotSupportedException {
                return super.clone();
            }
            // Mocking implementation of PublicCloneable if it were a real class
        });

        // Note: In a real JFreeChart environment, we'd use a real PublicCloneable class.
        // For this test, we assume the renderer is a standard renderer.
        plot.setRenderer(renderer);
        XYPlot clone = (XYPlot) plot.clone();
        assertNotNull(clone.getRenderer());
    }

    @Test
    public void testCloneWithNullFixedElements() throws CloneNotSupportedException {
        // Ensure no NullPointerException when fixed elements are null
        XYPlot clone = (XYPlot) plot.clone();
        assertNotNull(clone);
    }

    @Test
    public void testCloneWithQuadrantSettings() throws CloneNotSupportedException {
        // Testing quadrantPaint and quadrantOrigin
        // quadrantPaint is an array, needs to be initialized to avoid NPE in clone()
        // Since we can't set it directly via public API easily without knowing internal state, 
        // we rely on the fact that if it's initialized by default in constructor, it works.

        XYPlot clone = (XYPlot) plot.clone();
        assertNotNull(clone);
    }

    @Test
    public void testCloneComplexMapping() throws CloneNotSupportedException {
        plot.mapDatasetToDomainAxis(0, 0);
        plot.mapDatasetToRangeAxis(0, 0);

        XYPlot clone = (XYPlot) plot.clone();

        // Check if maps were copied
        // Since maps are private, we verify behavior if possible or assume success 
        // if no exception is thrown during the putAll calls.
        assertNotNull(clone);
    }

    @Test
    public void testCloneWithNullAxesInList() throws CloneNotSupportedException {
        // Testing the 'if (axis != null)' branch
        plot.setDomainAxis(0, null, false);

        // This should not throw NPE
        XYPlot clone = (XYPlot) plot.clone();
        assertNotNull(clone);
    }
}

/**
 * Dummy interface to simulate the requirement for the renderer branch.
 */
interface PublicCloneable {
    Object clone() throws CloneNotSupportedException;
}
